/**
 * Windows `acp-mcp-call` fallback: cmd.exe holds console output/exit for GUI-subsystem hosts, and
 * preferring standalone `node.exe` avoids Electron 44's multi-minute `ELECTRON_RUN_AS_NODE` exit lag.
 */
export const ACP_MCP_CALL_STANDALONE_SCRIPT = [
  "// Auto-generated by T3 Code for the Windows acp-mcp-call terminal fallback.",
  'const MCP_PROTOCOL_VERSION = "2025-06-18";',
  "const FALLBACK_EXIT_CODE = 125;",
  "",
  'if (typeof fetch !== "function") process.exit(FALLBACK_EXIT_CODE);',
  "",
  "const endpoint = process.env.T3_ACP_MCP_ENDPOINT;",
  "const authorization = process.env.T3_ACP_MCP_AUTHORIZATION;",
  "if (!endpoint || !authorization) {",
  '  process.stderr.write("acp-mcp-call requires T3_ACP_MCP_ENDPOINT and T3_ACP_MCP_AUTHORIZATION.\\n");',
  "  process.exit(2);",
  "}",
  "",
  "const [tool, argumentsArg] = process.argv.slice(2);",
  "if (!tool || argumentsArg === undefined) {",
  '  process.stderr.write("acp-mcp-call requires <tool> and <arguments-json>, or - to read it from stdin.\\n");',
  "  process.exit(2);",
  "}",
  "",
  "async function readStdin() {",
  "  const chunks = [];",
  "  for await (const chunk of process.stdin) {",
  '    chunks.push(typeof chunk === "string" ? Buffer.from(chunk) : chunk);',
  "  }",
  '  const text = Buffer.concat(chunks).toString("utf8");',
  '  return text.startsWith("\\uFEFF") ? text.slice(1) : text;',
  "}",
  "",
  "function parseSsePayloads(text) {",
  "  const payloads = [];",
  "  for (const rawEvent of text.split(/(?:\\r\\n|\\r(?!\\n)|\\n){2}/u)) {",
  "    const data = rawEvent",
  "      .split(/\\r\\n|\\r|\\n/u)",
  '      .filter((line) => line.startsWith("data:"))',
  "      .map((line) => line.slice(5).trimStart())",
  '      .join("\\n");',
  "    if (data.length > 0) payloads.push(JSON.parse(data));",
  "  }",
  "  return payloads;",
  "}",
  "",
  "async function main() {",
  '  const argumentsJson = argumentsArg === "-" ? await readStdin() : argumentsArg;',
  "  let parsed;",
  "  try {",
  "    parsed = JSON.parse(argumentsJson);",
  "  } catch {",
  '    process.stderr.write("acp-mcp-call arguments must be valid JSON.\\n");',
  "    process.exitCode = 2;",
  "    return;",
  "  }",
  '  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {',
  '    process.stderr.write("acp-mcp-call arguments must be a JSON object.\\n");',
  "    process.exitCode = 2;",
  "    return;",
  "  }",
  "",
  "  let sessionId = null;",
  "  let protocolVersion = null;",
  "  let nextId = 0;",
  "",
  "  const headers = () => ({",
  '    accept: "application/json, text/event-stream",',
  "    authorization,",
  '    connection: "close",',
  '    ...(sessionId === null ? {} : { "mcp-session-id": sessionId }),',
  '    ...(protocolVersion === null ? {} : { "mcp-protocol-version": protocolVersion }),',
  "  });",
  "",
  "  const send = async (message) => {",
  "    const response = await fetch(endpoint, {",
  '      method: "POST",',
  '      headers: { "content-type": "application/json", ...headers() },',
  "      body: JSON.stringify(message),",
  "    });",
  '    sessionId = response.headers.get("mcp-session-id") ?? sessionId;',
  "    if (!response.ok) {",
  "      await response.body?.cancel().catch(() => undefined);",
  "      throw new Error(`T3 Code MCP endpoint responded with HTTP ${response.status}.`);",
  "    }",
  "    if (response.status === 202 || response.status === 204) {",
  "      await response.body?.cancel().catch(() => undefined);",
  "      return [];",
  "    }",
  "    const text = await response.text();",
  '    const mediaType = (response.headers.get("content-type") ?? "").split(";", 1)[0].trim().toLowerCase();',
  '    const entries = mediaType === "text/event-stream"',
  "      ? parseSsePayloads(text)",
  "      : text.trim().length === 0",
  "        ? []",
  "        : [JSON.parse(text)];",
  "    const payloads = [];",
  "    for (const payload of entries) {",
  "      const version = payload?.result?.protocolVersion;",
  '      if (typeof version === "string" && version.length > 0) protocolVersion = version;',
  '      if (payload?.id !== undefined && typeof payload?.method === "string") {',
  "        const reply =",
  '          payload.method === "ping"',
  '            ? { jsonrpc: "2.0", id: payload.id, result: {} }',
  '            : { jsonrpc: "2.0", id: payload.id, error: { code: -32601, message: "Method not found" } };',
  "        await send(reply);",
  "        continue;",
  "      }",
  "      payloads.push(payload);",
  "    }",
  "    return payloads;",
  "  };",
  "",
  "  const request = async (method, params) => {",
  "    const id = `t3-cli-${nextId++}`;",
  '    const responses = await send({ jsonrpc: "2.0", id, method, params });',
  '    const envelope = responses.find((entry) => entry && typeof entry === "object" && entry.id === id) ?? null;',
  "    if (envelope === null || envelope.error !== undefined) {",
  '      throw new Error(`T3 Code MCP ${method} failed${envelope?.error === undefined ? "." : `: ${JSON.stringify(envelope.error)}`}`);',
  "    }",
  "    return envelope;",
  "  };",
  "",
  "  let result;",
  "  try {",
  '    await request("initialize", {',
  "      protocolVersion: MCP_PROTOCOL_VERSION,",
  "      capabilities: {},",
  '      clientInfo: { name: "t3-code-acp-cli", version: "0.0.0" },',
  "    });",
  '    await send({ jsonrpc: "2.0", method: "notifications/initialized" });',
  '    const envelope = await request("tools/call", { name: tool, arguments: parsed });',
  "    result = envelope.result;",
  "  } finally {",
  "    if (sessionId !== null) {",
  '      await fetch(endpoint, { method: "DELETE", headers: headers() })',
  "        .then((response) => response.body?.cancel().catch(() => undefined))",
  "        .catch(() => undefined);",
  "    }",
  "  }",
  "",
  "  if (",
  '    typeof result === "object" &&',
  "    result !== null &&",
  '    "structuredContent" in result &&',
  "    result.structuredContent !== undefined &&",
  "    Array.isArray(result.content)",
  "  ) {",
  "    const encoded = JSON.stringify(result.structuredContent);",
  "    result = {",
  "      ...result,",
  "      content: result.content.filter(",
  "        (part) =>",
  "          !(",
  '            typeof part === "object" &&',
  "            part !== null &&",
  '            part.type === "text" &&',
  "            part.text === encoded",
  "          ),",
  "      ),",
  "    };",
  "  }",
  "  process.stdout.write(`${JSON.stringify(result)}\\n`);",
  "}",
  "",
  "main().catch((error) => {",
  "  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\\n`);",
  "  process.exitCode = 1;",
  "});",
  "",
].join("\n");

// cmd.exe decodes batch files with the console code page, so paths come from the (UTF-16) environment.
export const ACP_MCP_CALL_LAUNCHER = [
  "@echo off",
  "setlocal EnableExtensions DisableDelayedExpansion",
  'set "T3_CALL_SCRIPT=%T3_ACP_MCP_CALL_SCRIPT%"',
  'if not defined T3_CALL_SCRIPT if exist "%~dp0acp-mcp-call.mjs" set "T3_CALL_SCRIPT=%~dp0acp-mcp-call.mjs"',
  "if not defined T3_CALL_SCRIPT goto fallback",
  "where /q node.exe >nul 2>nul",
  "if errorlevel 1 goto fallback",
  'node.exe "%T3_CALL_SCRIPT%" %*',
  'if not "%errorlevel%"=="125" exit /b %errorlevel%',
  ":fallback",
  'set "ELECTRON_RUN_AS_NODE=1"',
  "if not defined T3_ACP_MCP_ENTRYPOINT goto packaged",
  '"%T3_ACP_MCP_NODE%" "%T3_ACP_MCP_ENTRYPOINT%" acp-mcp-call %*',
  "exit /b %errorlevel%",
  ":packaged",
  '"%T3_ACP_MCP_NODE%" acp-mcp-call %*',
  "",
].join("\r\n");
